// PayPal sandbox integration.
// Orders + Payments go through the official TypeScript Server SDK (@paypal/paypal-server-sdk, generated by APIMatic).
// Webhook signature verification and webhook registration are not in the SDK, so they use fetch.
import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  LogLevel,
  OrdersController,
  PaymentsController,
  PaypalExperienceLandingPage,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
} from "@paypal/paypal-server-sdk";
import { PAYPAL_API_BASE, env } from "./env";
import { toPayPal } from "../shared/money";

const client = new Client({
  clientCredentialsAuthCredentials: {
    oAuthClientId: env.PAYPAL_CLIENT_ID,
    oAuthClientSecret: env.PAYPAL_CLIENT_SECRET,
  },
  environment: Environment.Sandbox, // sandbox only, by design
  timeout: 30_000,
  httpClientOptions: { retryConfig: { maxNumberOfRetries: 0 } }, // retries are owned by our persistent queue
  // SDK request logging stays OFF (it would print every call); set PAYPAL_SDK_LOG=1 to debug, with headers masked and no bodies.
  ...(process.env.PAYPAL_SDK_LOG === "1"
    ? { logging: { logLevel: LogLevel.Info, maskSensitiveHeaders: true, logRequest: { logBody: false, logHeaders: false }, logResponse: { logBody: false, logHeaders: false } } }
    : {}),
});
const orders = new OrdersController(client);
const payments = new PaymentsController(client);

// ---------- error classification ----------

export type ErrorClass = "RETRYABLE" | "TERMINAL" | "CONFIG" | "WAIT";

export interface PayPalFailure {
  status: number;
  issue: string;
  description: string;
  debugId?: string;
  retryAfterMs?: number;
  cls: ErrorClass;
}

function header(headers: unknown, name: string): string | undefined {
  if (!headers || typeof headers !== "object") return undefined;
  const hit = Object.entries(headers as Record<string, unknown>).find(([k]) => k.toLowerCase() === name);
  return hit ? String(hit[1]) : undefined;
}

/** Error taxonomy follows the APIMatic Context Plugin skill `paypal:typescript-error-handling`. */
export function classify(e: unknown): PayPalFailure {
  if (e instanceof ApiError) {
    type PayPalErrorBody = { name?: string; message?: string; debug_id?: string; details?: { issue?: string; description?: string }[] };
    let body = (e as unknown as { result?: PayPalErrorBody }).result;
    if (!body && typeof e.body === "string") {
      try {
        body = JSON.parse(e.body) as PayPalErrorBody;
      } catch {
        body = { message: e.body.slice(0, 200) };
      }
    }
    const issue = body?.details?.[0]?.issue ?? body?.name ?? "UNKNOWN";
    const description = body?.details?.[0]?.description ?? body?.message ?? "";
    const status = e.statusCode;
    const retryAfter = Number(header(e.headers, "retry-after"));
    let cls: ErrorClass = "TERMINAL";
    if (status === 429 || status >= 500) cls = "RETRYABLE";
    else if (status === 401 || status === 403) cls = "CONFIG";
    else if (issue === "ORDER_NOT_APPROVED") cls = "WAIT";
    return {
      status,
      issue,
      description,
      debugId: body?.debug_id ?? header(e.headers, "paypal-debug-id"),
      retryAfterMs: Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : undefined,
      cls,
    };
  }
  const err = e instanceof Error ? e : new Error(String(e));
  const code = (err as Error & { code?: string }).code ?? "";
  if (err.name === "AbortError" || err.name === "TimeoutError" || /^(ECONN|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|ECONNRESET|ERR_NETWORK)/.test(code) || /network|socket|timeout/i.test(err.message)) {
    return { status: 0, issue: "NETWORK", description: err.message, cls: "RETRYABLE" };
  }
  if (err.message.startsWith("Required authentication credentials")) return { status: 0, issue: "CREDENTIALS", description: err.message, cls: "CONFIG" };
  return { status: 0, issue: err.name || "ERROR", description: err.message, cls: "TERMINAL" };
}

/** Per-call deadline (the SDK timeout is per attempt and does not cover the token fetch). */
const deadline = () => ({ abortSignal: AbortSignal.timeout(45_000) });

// ---------- orders ----------

export interface CreateHoldInput {
  dropId: string;
  entryId: string;
  title: string;
  sku: string;
  priceCents: number;
  shipHoldCents: number;
  returnUrl: string;
  cancelUrl: string;
}

export async function createHoldOrder(i: CreateHoldInput): Promise<{ orderId: string; approveUrl?: string }> {
  const total = i.priceCents + i.shipHoldCents;
  const { result } = await orders.createOrder(
    {
    paypalRequestId: `create:${i.entryId}`,
    prefer: "return=representation",
    body: {
      intent: CheckoutPaymentIntent.Authorize,
      purchaseUnits: [
        {
          referenceId: i.dropId,
          customId: `${i.dropId}:${i.entryId}`,
          description: `Paylet allocation ballot — right to purchase "${i.title}" at list price`,
          softDescriptor: "PAYLET",
          amount: {
            currencyCode: "USD",
            value: toPayPal(total),
            breakdown: {
              itemTotal: { currencyCode: "USD", value: toPayPal(i.priceCents) },
              shipping: { currencyCode: "USD", value: toPayPal(i.shipHoldCents) },
            },
          },
          items: [{ name: i.title.slice(0, 127), quantity: "1", sku: i.sku, unitAmount: { currencyCode: "USD", value: toPayPal(i.priceCents) } }],
        },
      ],
      paymentSource: {
        paypal: {
          experienceContext: {
            brandName: "Paylet",
            locale: "en-US",
            shippingPreference: PaypalWalletContextShippingPreference.GetFromFile,
            userAction: PaypalExperienceUserAction.Continue,
            landingPage: PaypalExperienceLandingPage.Login,
            returnUrl: i.returnUrl,
            cancelUrl: i.cancelUrl,
          },
        },
      },
    },
    },
    deadline(),
  );
  if (!result.id) throw new Error("createOrder: PayPal returned no order id");
  const approveUrl = result.links?.find((l) => l.rel === "payer-action")?.href ?? result.links?.find((l) => l.rel === "approve")?.href;
  return { orderId: result.id, approveUrl };
}

export interface OrderIdentity {
  status: string;
  payerId?: string;
  accountId?: string;
  accountStatus?: string;
  email?: string;
  name?: string;
  address?: { line1: string; line2?: string; city?: string; state?: string; zip?: string; country?: string };
}

/** Server-side only: identity fields never leave the backend in clear. */
export async function getOrderIdentity(orderId: string): Promise<OrderIdentity> {
  const { result: o } = await orders.getOrder({ id: orderId }, deadline());
  const pp = o.paymentSource?.paypal;
  const ship = o.purchaseUnits?.[0]?.shipping;
  const a = ship?.address;
  const nm = o.payer?.name;
  return {
    status: String(o.status ?? ""),
    payerId: o.payer?.payerId,
    accountId: pp?.accountId,
    accountStatus: pp?.accountStatus ? String(pp.accountStatus) : undefined,
    email: o.payer?.emailAddress ?? pp?.emailAddress,
    name: ship?.name?.fullName ?? [nm?.givenName, nm?.surname].filter(Boolean).join(" "),
    address: a
      ? { line1: a.addressLine1 ?? "", line2: a.addressLine2, city: a.adminArea2, state: a.adminArea1, zip: a.postalCode, country: a.countryCode }
      : undefined,
  };
}

export async function authorizeOrder(orderId: string, requestId: string) {
  const { result } = await orders.authorizeOrder({ id: orderId, paypalRequestId: requestId, prefer: "return=representation" }, deadline());
  const auth = result.purchaseUnits?.[0]?.payments?.authorizations?.[0];
  return { authorizationId: auth?.id, status: String(auth?.status ?? ""), amount: auth?.amount?.value, expiresAt: auth?.expirationTime };
}

// ---------- payments ----------

export async function getAuthorization(authorizationId: string) {
  const { result } = await payments.getAuthorizedPayment({ authorizationId }, deadline());
  return { status: String(result.status ?? ""), amount: result.amount?.value };
}

export async function captureAuthorization(authorizationId: string, amountCents: number, requestId: string, invoiceId: string) {
  const { result } = await payments.captureAuthorizedPayment({
    authorizationId,
    paypalRequestId: requestId,
    prefer: "return=representation",
    body: {
      amount: { currencyCode: "USD", value: toPayPal(amountCents) },
      finalCapture: true,
      invoiceId,
      noteToPayer: "Your Paylet allocation — thanks for buying direct from the maker.",
      softDescriptor: "PAYLET",
    },
  }, deadline());
  return { captureId: result.id, status: String(result.status ?? ""), amount: result.amount?.value };
}

/** Void is not idempotent on PayPal's side: GET first, treat PREVIOUSLY_VOIDED as success. */
export async function voidAuthorizationSafe(authorizationId: string, requestId: string): Promise<{ status: string; already?: boolean }> {
  const current = await getAuthorization(authorizationId);
  if (current.status === "VOIDED") return { status: "VOIDED", already: true };
  if (current.status === "CAPTURED" || current.status === "PARTIALLY_CAPTURED") return { status: current.status, already: true };
  try {
    await payments.voidPayment({ authorizationId, paypalRequestId: requestId, prefer: "return=minimal" }, deadline());
    return { status: "VOIDED" };
  } catch (e) {
    const f = classify(e);
    if (f.issue === "PREVIOUSLY_VOIDED" || f.issue === "AUTHORIZATION_VOIDED") return { status: "VOIDED", already: true };
    throw e;
  }
}

// ---------- raw REST (webhooks) ----------

let token: { value: string; exp: number } | undefined;
let inflight: Promise<string> | undefined;
async function accessToken(): Promise<string> {
  if (token && token.exp > Date.now() + 60_000) return token.value;
  inflight ??= fetchToken().finally(() => (inflight = undefined));
  return inflight;
}
async function fetchToken(): Promise<string> {
  const res = await fetch(`${PAYPAL_API_BASE}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${Buffer.from(`${env.PAYPAL_CLIENT_ID}:${env.PAYPAL_CLIENT_SECRET}`).toString("base64")}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok) throw new Error(`oauth ${res.status} debug_id=${res.headers.get("paypal-debug-id") ?? "-"}`);
  const j = (await res.json()) as { access_token: string; expires_in: number };
  token = { value: j.access_token, exp: Date.now() + j.expires_in * 1000 };
  return token.value;
}

async function rest<T>(method: string, path: string, body?: unknown): Promise<{ status: number; json: T }> {
  const res = await fetch(`${PAYPAL_API_BASE}${path}`, {
    method,
    headers: { Authorization: `Bearer ${await accessToken()}`, "Content-Type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
    signal: AbortSignal.timeout(20_000),
  });
  const text = await res.text();
  if (res.status >= 400) throw new Error(`PayPal ${method} ${path} → ${res.status} debug_id=${res.headers.get("paypal-debug-id") ?? "-"} ${text.slice(0, 160)}`);
  return { status: res.status, json: (text ? JSON.parse(text) : {}) as T };
}

export async function verifyWebhookSignature(headers: Headers, rawBody: string, webhookId: string): Promise<boolean> {
  const h = (k: string) => headers.get(k) ?? "";
  if (!h("paypal-transmission-id") || !webhookId) return false;
  // PayPal requires the original event object; re-parse without re-ordering keys.
  const payload = `{"auth_algo":${JSON.stringify(h("paypal-auth-algo"))},"cert_url":${JSON.stringify(h("paypal-cert-url"))},"transmission_id":${JSON.stringify(
    h("paypal-transmission-id"),
  )},"transmission_sig":${JSON.stringify(h("paypal-transmission-sig"))},"transmission_time":${JSON.stringify(
    h("paypal-transmission-time"),
  )},"webhook_id":${JSON.stringify(webhookId)},"webhook_event":${rawBody}}`;
  const res = await fetch(`${PAYPAL_API_BASE}/v1/notifications/verify-webhook-signature`, {
    method: "POST",
    headers: { Authorization: `Bearer ${await accessToken()}`, "Content-Type": "application/json" },
    body: payload,
    signal: AbortSignal.timeout(20_000),
  });
  if (!res.ok) return false;
  const j = (await res.json()) as { verification_status?: string };
  return j.verification_status === "SUCCESS";
}

export const WEBHOOK_EVENTS = [
  "CHECKOUT.ORDER.APPROVED",
  "PAYMENT.AUTHORIZATION.CREATED",
  "PAYMENT.AUTHORIZATION.VOIDED",
  "PAYMENT.CAPTURE.COMPLETED",
  "PAYMENT.CAPTURE.DENIED",
  "PAYMENT.CAPTURE.REFUNDED",
];

/** Finds or creates the webhook for `${PUBLIC_URL}/webhooks/paypal`. Returns its id, or "" if not possible (e.g. localhost). */
export async function ensureWebhook(publicUrl: string): Promise<string> {
  if (!publicUrl.startsWith("https://")) return "";
  const url = `${publicUrl.replace(/\/$/, "")}/webhooks/paypal`;
  const list = await rest<{ webhooks?: { id: string; url: string }[] }>("GET", "/v1/notifications/webhooks");
  const existing = list.json.webhooks?.find((w) => w.url === url);
  if (existing) return existing.id;
  const created = await rest<{ id?: string }>("POST", "/v1/notifications/webhooks", {
    url,
    event_types: WEBHOOK_EVENTS.map((name) => ({ name })),
  });
  return created.json.id ?? "";
}
